export function getBrand(id: string): BrandDef | undefined {
  return all[id]
}

export function BrandIcon({ id, size = 24, className }: { id: string; size?: number; className?: string }) {
  const brand = getBrand(id)
  if (!brand) return null
  const Comp = brand.component
  return <Comp width={size} height={size} className={className} />
}
